-- Migration 024: agent profile with first name, last name, email and WhatsApp (2026-10-26).
-- The owner registers agents with first and last name, official email and WhatsApp number (all
-- required); the unique code is still generated by the database. The role becomes optional.
-- full_name stays the public display name and is derived from first and last name.

alter table public.agents add column if not exists first_name text;
alter table public.agents add column if not exists last_name text;
do $constraint$ begin
  if not exists (select 1 from pg_constraint where conname = 'agents_first_name_check' and conrelid = 'public.agents'::regclass) then
    alter table public.agents add constraint agents_first_name_check
      check (first_name is null or (char_length(btrim(first_name)) between 1 and 59 and first_name !~ '[[:cntrl:]]'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'agents_last_name_check' and conrelid = 'public.agents'::regclass) then
    alter table public.agents add constraint agents_last_name_check
      check (last_name is null or (char_length(btrim(last_name)) between 1 and 59 and last_name !~ '[[:cntrl:]]'));
  end if;
end $constraint$;

-- Creates (p_id null) or updates an agent and returns its id and unique code.
-- p_whatsapp is stored in the phone column in international format (E.164).
create or replace function public.save_agent_profile(
  p_id uuid, p_first_name text, p_last_name text, p_email text, p_whatsapp text, p_title text, p_languages text[], p_active boolean
) returns table (saved_id uuid, saved_code text) language plpgsql security definer set search_path = '' as $$
declare v_id uuid := p_id; v_code text; alphabet text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'; actor_email text;
  previous public.agents%rowtype; v_first text := btrim(p_first_name); v_last text := btrim(p_last_name);
  -- Without a role the agent is shown as a "Brickwise agent", translated in the interface.
  role_title text := coalesce(nullif(btrim(p_title), ''), 'Brickwise agent');
begin
  if not public.is_verified_admin() then raise exception 'AGENT_ADMIN_REQUIRED'; end if;
  if p_active is null or nullif(v_first, '') is null or nullif(v_last, '') is null then raise exception 'AGENT_INVALID'; end if;
  if nullif(btrim(p_email), '') is null or nullif(btrim(p_whatsapp), '') is null then raise exception 'AGENT_CONTACT_REQUIRED'; end if;
  select email into actor_email from auth.users where id = auth.uid();
  if v_id is null then
    loop
      v_code := 'BW-' || (select string_agg(substr(alphabet, 1 + floor(random() * 32)::int, 1), '') from generate_series(1, 6));
      exit when not exists (select 1 from public.agents a where a.code = v_code);
    end loop;
    insert into public.agents(code, first_name, last_name, full_name, title, email, phone, languages, active, created_by, deactivated_at)
    values (v_code, v_first, v_last, v_first || ' ' || v_last, role_title, lower(btrim(p_email)), btrim(p_whatsapp),
      coalesce(p_languages, '{}'), p_active, auth.uid(), case when p_active then null else now() end)
    returning id into v_id;
  else
    select * into previous from public.agents a where a.id = v_id for update;
    if not found then raise exception 'AGENT_NOT_FOUND'; end if;
    v_code := previous.code;
    update public.agents a set first_name = v_first, last_name = v_last, full_name = v_first || ' ' || v_last, title = role_title,
      email = lower(btrim(p_email)), phone = btrim(p_whatsapp), languages = coalesce(p_languages, '{}'), active = p_active, updated_at = now(),
      deactivated_at = case when p_active then null when previous.active then now() else previous.deactivated_at end
    where a.id = v_id;
  end if;
  insert into public.admin_audit_logs(actor_id, actor_email, action, target_type, target_id, status, details)
  values (auth.uid(), actor_email, case when p_id is null then 'agent.create' else 'agent.update' end, 'agent', v_id::text, 'success',
    jsonb_build_object('code', v_code, 'fullName', v_first || ' ' || v_last, 'title', role_title, 'active', p_active,
      'email', lower(btrim(p_email)), 'whatsapp', btrim(p_whatsapp)));
  return query select v_id, v_code;
end;
$$;

-- The previous save function is replaced by save_agent_profile.
revoke all on function public.save_agent(uuid, text, text, text, text, text[], boolean) from public, anon, authenticated, service_role;
revoke all on function public.save_agent_profile(uuid, text, text, text, text, text, text[], boolean) from public, anon, authenticated, service_role;
grant execute on function public.save_agent_profile(uuid, text, text, text, text, text, text[], boolean) to authenticated;

notify pgrst, 'reload schema';
